package com.cartalaap.marketplace;
import java.math.BigDecimal;import java.util.List;import org.hibernate.validator.constraints.URL;import jakarta.validation.Valid;import jakarta.validation.constraints.DecimalMin;import jakarta.validation.constraints.Max;import jakarta.validation.constraints.Min;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.NotEmpty;import jakarta.validation.constraints.NotNull;import jakarta.validation.constraints.Size;
public record ListingRequest(@NotNull ListingCategory category,@NotBlank @Size(max=160) String title,@NotBlank @Size(max=5000) String description,@NotNull @DecimalMin("0.00") BigDecimal price,@NotNull ListingCondition condition,@NotBlank @Size(max=120) String location,@Size(max=80) String brand,@Size(max=80) String model,@Min(1886) @Max(2100) Integer year,@Min(0) Long mileage,@NotEmpty @Size(max=8) List<@Valid @URL @Size(max=2048) String> imageUrls){public boolean maxInvalid(){return price==null||price.signum()<0||year!=null&&(year<1886||year>2100)||mileage!=null&&mileage<0;}}
